cat > /workspace/color.go <<'EOF'
package main

import (
	"fmt"
	"os"
)

// colorEnabled is set once at startup.
var colorEnabled = false

// detectColor reports whether stdout is a terminal.
func detectColor() {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return
	}
	if (fi.Mode() & os.ModeCharDevice) != 0 {
		colorEnabled = true
	}
}

// wrap wraps s with an ANSI color code using the \x1b[0;22m trailer (reset+normal).
func wrap(code int, s string) string {
	if !colorEnabled {
		return s
	}
	return fmt.Sprintf("\x1b[%d;1m%s\x1b[0;22m", code, s)
}

// block wraps a line (including trailing \n) with an ANSI color code using \x1b[0m.
func block(code int, s string) string {
	if !colorEnabled {
		return s
	}
	return fmt.Sprintf("\x1b[%d;1m%s\x1b[0m", code, s)
}

// hashColor colours each '#' character in s individually.
func hashColor(s string) string {
	if !colorEnabled {
		return s
	}
	out := make([]byte, 0, len(s)*2)
	for i := 0; i < len(s); i++ {
		if s[i] == '#' {
			out = append(out, "\x1b[90;1m#\x1b[0;22m"...)
		} else {
			out = append(out, s[i])
		}
	}
	return string(out)
}
EOF
echo done

