cat > /workspace/flags.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Options mirrors the application CLI options.
type Options struct {
	Count     int
	Privilege bool
	Version   bool
	Help      bool
}

// parseArgs parses command-line arguments in a style compatible with the go-flags
// library used by the original pingu binary.
//
// Returned errors correspond to the messages produced by the reference implementation:
//   - unknown flag `X'
//   - expected argument for flag `-c, --count'
//   - invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing "V": invalid syntax
//   - too many arguments
func parseArgs(args []string) (opts Options, host string, err error) {
	opts.Count = 20

	setCount := func(value string) error {
		n, perr := strconv.ParseInt(value, 0, 64)
		if perr != nil {
			return fmt.Errorf("invalid argument for flag `-c, --count' (expected int): %s", perr.Error())
		}
		opts.Count = int(n)
		return nil
	}

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx != -1 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			switch name {
			case "count":
				if !hasValue {
					if i+1 >= len(args) {
						return opts, "", fmt.Errorf("expected argument for flag `-c, --count'")
					}
					i++
					value = args[i]
				}
				if err := setCount(value); err != nil {
					return opts, "", err
				}
			case "privilege":
				if hasValue {
					return opts, "", fmt.Errorf("bool flag `--privilege' cannot have a value")
				}
				opts.Privilege = true
			case "version":
				if hasValue {
					return opts, "", fmt.Errorf("bool flag `--version' cannot have a value")
				}
				opts.Version = true
			case "help":
				if hasValue {
					return opts, "", fmt.Errorf("bool flag `--help' cannot have a value")
				}
				opts.Help = true
			default:
				return opts, "", fmt.Errorf("unknown flag `%s'", name)
			}
			i++
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			// short flags
			j := 1
			for j < len(arg) {
				c := arg[j]
				switch c {
				case 'c':
					var value string
					if j+1 < len(arg) {
						rest := arg[j+1:]
						if strings.HasPrefix(rest, "=") {
							value = rest[1:]
						} else {
							value = rest
						}
					} else {
						if i+1 >= len(args) {
							return opts, "", fmt.Errorf("expected argument for flag `-c, --count'")
						}
						i++
						value = args[i]
					}
					if err := setCount(value); err != nil {
						return opts, "", err
					}
					j = len(arg) // consume the rest
				case 'P':
					opts.Privilege = true
					j++
				case 'V':
					opts.Version = true
					j++
				case 'h':
					opts.Help = true
					j++
				default:
					return opts, "", fmt.Errorf("unknown flag `%c'", c)
				}
			}
			i++
			continue
		}
		positional = append(positional, arg)
		i++
	}

	switch len(positional) {
	case 0:
		host = ""
	case 1:
		host = positional[0]
	default:
		return opts, "", fmt.Errorf("too many arguments")
	}
	return
}
EOF
echo done

