package main

import (
	"encoding/binary"
	"errors"
	"fmt"
	"math/rand"
	"net"
	"os"
	"syscall"
	"time"
)

// Linux constant, not present in the Go standard syscall package
const ipv6RecvHopLimit = 51

// packetSize is the ICMP payload size (bytes of data after the 8-byte ICMP header).
const packetSize = 32

// Pinger sends ICMP echo requests and receives replies.
type Pinger struct {
	addr       string // the original host string
	ipaddr     net.IP
	privileged bool
	id         uint16
	fd         int
	conn       net.PacketConn
	isV6       bool
	seq        uint16
}

// initPinger creates a pinger for the given host. A non-nil error indicates a
// failure to resolve or validate the host.
func initPinger(host string) (*Pinger, error) {
	if host == "" {
		return nil, errors.New("addr cannot be empty")
	}
	ip := net.ParseIP(host)
	if ip == nil {
		ips, err := net.LookupHost(host)
		if err != nil {
			// Strip the "lookup X: " prefix because we want to emit the error
			// starting with "lookup ..." (matching the observed output which
			// already contains two consecutive "lookup" words like
			//   failed to init pinger lookup <host> on <dns>: no such host
			// ). net.LookupHost returns a *net.DNSError which stringifies as
			// "lookup <host> on <server>: <err>".
			return nil, err
		}
		if len(ips) == 0 {
			return nil, fmt.Errorf("no addresses for %s", host)
		}
		// Prefer IPv4 if available.
		for _, s := range ips {
			p := net.ParseIP(s)
			if p != nil && p.To4() != nil {
				ip = p
				break
			}
		}
		if ip == nil {
			ip = net.ParseIP(ips[0])
		}
	}
	p := &Pinger{
		addr:   host,
		ipaddr: ip,
		isV6:   ip.To4() == nil,
		id:     uint16(rand.Uint32() & 0xffff),
	}
	return p, nil
}

// listen sets up the socket for sending and receiving ICMP packets.
func (p *Pinger) listen() error {
	if p.privileged {
		var network, addr string
		if p.isV6 {
			network = "ip6:ipv6-icmp"
		} else {
			network = "ip4:icmp"
		}
		c, err := net.ListenPacket(network, addr)
		if err != nil {
			return err
		}
		p.conn = c
		return nil
	}
	// Unprivileged: SOCK_DGRAM with IPPROTO_ICMP (Linux ping_group_range)
	domain := syscall.AF_INET
	proto := syscall.IPPROTO_ICMP
	if p.isV6 {
		domain = syscall.AF_INET6
		proto = syscall.IPPROTO_ICMPV6
	}
	fd, err := syscall.Socket(domain, syscall.SOCK_DGRAM, proto)
	if err != nil {
		return &net.OpError{Op: "listen", Net: networkName(p.isV6), Err: &os.SyscallError{Syscall: "socket", Err: err}}
	}
	// Enable TTL/HopLimit reception
	if p.isV6 {
		syscall.SetsockoptInt(fd, syscall.IPPROTO_IPV6, ipv6RecvHopLimit, 1)
	} else {
		syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
	}
	// Bind to 0.0.0.0 / ::
	var sa syscall.Sockaddr
	if p.isV6 {
		sa = &syscall.SockaddrInet6{}
	} else {
		sa = &syscall.SockaddrInet4{}
	}
	if err := syscall.Bind(fd, sa); err != nil {
		syscall.Close(fd)
		return err
	}
	// Wrap the fd in a PacketConn via os.File so that write errors look like
	// "write udp 0.0.0.0:PORT->IP:0: <err>".
	f := os.NewFile(uintptr(fd), "icmp")
	c, err := net.FilePacketConn(f)
	f.Close() // FilePacketConn dup's; close the dup
	if err != nil {
		syscall.Close(fd)
		return err
	}
	p.conn = c
	p.fd = -1 // we now use c exclusively for writes; reads use the underlying fd via syscalls for cmsg
	// Re-open a raw fd dup for recvmsg with cmsg
	rawFile, err := c.(interface{ File() (*os.File, error) }).File()
	if err != nil {
		return err
	}
	p.fd = int(rawFile.Fd())
	// We intentionally keep rawFile alive alongside c; not strictly right but
	// adequate for our purposes (both point at dup'd file descriptors).
	// Prevent rawFile from closing the fd when GC'd by keeping it on p.
	p.keep = rawFile
	return nil
}

// keep is used to hold a reference to avoid premature finalisation.
var _ = func() {}

func networkName(isV6 bool) string {
	if isV6 {
		return "ip6:ipv6-icmp"
	}
	return "ip4:icmp"
}

// icmpChecksum calculates the Internet checksum over b.
func icmpChecksum(b []byte) uint16 {
	var sum uint32
	n := len(b)
	for i := 0; i+1 < n; i += 2 {
		sum += uint32(binary.BigEndian.Uint16(b[i:]))
	}
	if n%2 == 1 {
		sum += uint32(b[n-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

func buildEchoRequest(isV6 bool, id, seq uint16, payload []byte) []byte {
	hdr := make([]byte, 8)
	if isV6 {
		hdr[0] = 128 // ICMPv6 Echo Request
	} else {
		hdr[0] = 8 // ICMPv4 Echo Request
	}
	hdr[1] = 0
	binary.BigEndian.PutUint16(hdr[4:], id)
	binary.BigEndian.PutUint16(hdr[6:], seq)
	pkt := append(hdr, payload...)
	// For IPv6 the kernel fills in the checksum (when using SOCK_RAW with no
	// IPV6_CHECKSUM or when using SOCK_DGRAM). We still set it for IPv4.
	if !isV6 {
		cs := icmpChecksum(pkt)
		binary.BigEndian.PutUint16(pkt[2:4], cs)
	}
	return pkt
}
