		switch fa := from.(type) {
		case *syscall.SockaddrInet4:
			peer = net.IP(fa.Addr[:])
		case *syscall.SockaddrInet6:
			peer = net.IP(fa.Addr[:])
		}
		return &Reply{Seq: int(seq), NBytes: packetSize, TTL: ttl, RTT: rtt, Peer: peer}, nil
	}
}

// extractInt reads a host-order int from 1 or 4 bytes of cmsg data.
func extractInt(b []byte) int {
	switch len(b) {
	case 0:
		return 0
	case 1:
		return int(b[0])
	case 2:
		return int(binary.LittleEndian.Uint16(b))
	default:
		return int(binary.LittleEndian.Uint32(b[:4]))
	}
}

// wrapSendErr wraps a sendto error in a net.OpError mimicking the reference
// binary's output format: "write udp LOCAL->REMOTE: sendmsg: <err>".
func (p *Pinger) wrapSendErr(err error) error {
	var local, remote net.Addr
	if p.isV6 {
		local = &net.UDPAddr{IP: net.IPv6zero, Port: p.localPort}
		remote = &net.UDPAddr{IP: p.ipaddr}
	} else {
		local = &net.UDPAddr{IP: net.IPv4zero, Port: p.localPort}
		remote = &net.UDPAddr{IP: p.ipaddr}
	}
	return &net.OpError{
		Op:     "write",
		Net:    "udp",
		Source: local,
		Addr:   remote,
		Err:    &os.SyscallError{Syscall: "sendmsg", Err: err},
	}
}
