		wrap(94, min.String()),
		wrap(96, avg.String()),
		wrap(92, max.String()),
		wrap(35, std.String()),
	)
}

// rttSummary computes min/avg/max/stddev of the RTT set, mirroring the
// reference binary. When the set is empty all values are 0.
func rttSummary(rtts []time.Duration) (min, avg, max, stddev time.Duration) {
	if len(rtts) == 0 {
		return 0, 0, 0, 0
	}
	min = rtts[0]
	max = rtts[0]
	var sum time.Duration
	for _, r := range rtts {
		if r < min {
			min = r
		}
		if r > max {
			max = r
		}
		sum += r
	}
	avg = sum / time.Duration(len(rtts))
	if len(rtts) < 2 {
		return
	}
	var sq float64
	for _, r := range rtts {
		d := float64(r - avg)
		sq += d * d
	}
	stddev = time.Duration(math.Sqrt(sq / float64(len(rtts))))
	return
}
