	printed := false
	defer func() {
		if !printed {
			printStats(&st)
		}
	}()

	var i int
	for {
		if count > 0 && i >= count {
			break
		}
		select {
		case <-stop:
			return nil
		default:
		}
		seq := uint16(i)
		st.transmitted++
		reply, err := p.send(seq, timeout)
		if err != nil {
			return err
		}
		if reply != nil {
			st.received++
			st.rtts = append(st.rtts, reply.RTT)
			printReply(p, reply)
		}
		i++
		if count > 0 && i >= count {
			break
		}
		// Sleep for the interval, but wake on signal.
		select {
		case <-stop:
			return nil
		case <-time.After(interval):
		}
	}
	printStats(&st)
	printed = true
	return nil
}

// printReply prints one ping reply line to stdout.
func printReply(p *Pinger, r *Reply) {
	frame := penguinFrames[r.Seq%len(penguinFrames)]
	frame = hashColor(frame)
	fmt.Printf("%sseq=%s %sbytes from %s: ttl=%s time=%s\n",
		frame,
		wrap(93, fmt.Sprintf("%d", r.Seq)),
		wrap(94, fmt.Sprintf("%d", r.NBytes)),
		wrap(37, p.ipaddr.String()),
		wrap(96, fmt.Sprintf("%d", r.TTL)),
		wrap(95, r.RTT.String()),
	)
}

// printStats prints the summary statistics block.
func printStats(st *stats) {
	fmt.Print(block(37, fmt.Sprintf("\n───────── %s ping statistics ─────────\n", st.host)))
	loss := 0.0
	if st.transmitted > 0 {
		loss = float64(st.transmitted-st.received) / float64(st.transmitted) * 100
	}
	fmt.Printf("%s: %s transmitted => %s received (%s loss)\n",
		wrap(97, "PACKET STATISTICS"),
		wrap(94, fmt.Sprintf("%d", st.transmitted)),
		wrap(92, fmt.Sprintf("%d", st.received)),
		wrap(91, fmt.Sprintf("%d%%", int(loss+0.5))),
	)
	min, avg, max, std := rttSummary(st.rtts)
	fmt.Printf("%s: min=%s avg=%s max=%s stddev=%s\n",
		wrap(97, "ROUND TRIP"),
		wrap(94, min.String()),
		wrap(96, avg.String()),
		wrap(92, max.String()),
		wrap(35, std.String()),
	)
}

// rttSummary computes min/avg/max/stddev of the RTT set, mirroring the
// reference binary. When the set is empty all values are 0.
func rttSummary(rtts []time.Duration) (min, avg, max, stddev time.Duration) {
	if len(rtts) == 0 {
		return 0, 0, 0, 0
	}
	min = rtts[0]
	max = rtts[0]
	var sum time.Duration
	for _, r := range rtts {
		if r < min {
			min = r
		}
		if r > max {
			max = r
		}
		sum += r
	}
	avg = sum / time.Duration(len(rtts))
	if len(rtts) < 2 {
		return
	}
	var sq float64
	for _, r := range rtts {
		d := float64(r - avg)
		sq += d * d
	}
	stddev = time.Duration(math.Sqrt(sq / float64(len(rtts))))
	return
}
