// Options mirrors the application CLI options.
type Options struct {
	Count     int
	Privilege bool
	Version   bool
	Help      bool
}

// parseErr is the error type used for all go-flags-style parsing errors. Such
// errors are printed by the go-flags library in addition to the application
// itself, producing two copies of the message (the first without the
// "parse error: " prefix, the second with it).
type parseErr struct{ msg string }

func (e *parseErr) Error() string { return e.msg }

func perr(format string, a ...interface{}) error {
	return &parseErr{msg: fmt.Sprintf(format, a...)}
}

// parseArgs parses command-line arguments in a style compatible with the
// go-flags library used by the original pingu binary.
func parseArgs(args []string) (opts Options, host string, hasHost bool, err error) {
	opts.Count = 20

	setCount := func(value string) error {
		n, perr2 := strconv.ParseInt(value, 0, 64)
		if perr2 != nil {
			return perr("invalid argument for flag `-c, --count' (expected int): %s", perr2.Error())
		}
		opts.Count = int(n)
		return nil
	}

	var positional []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx != -1 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			switch name {
			case "count":
				if !hasValue {
					if i+1 >= len(args) {
						return opts, "", false, perr("expected argument for flag `-c, --count'")
					}
					i++
					value = args[i]
				}
				if err := setCount(value); err != nil {
					return opts, "", false, err
				}
			case "privilege":
				if hasValue {
					return opts, "", false, perr("bool flag `--privilege' cannot have a value")
				}
				opts.Privilege = true
			case "version":
				if hasValue {
					return opts, "", false, perr("bool flag `--version' cannot have a value")
				}
				opts.Version = true
			case "help":
				if hasValue {
					return opts, "", false, perr("bool flag `--help' cannot have a value")
				}
				opts.Help = true
			default:
				return opts, "", false, perr("unknown flag `%s'", name)
			}
			i++
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			j := 1
			for j < len(arg) {
				c := arg[j]
				switch c {
				case 'c':
					var value string
					if j+1 < len(arg) {
						rest := arg[j+1:]
						if strings.HasPrefix(rest, "=") {
							value = rest[1:]
						} else {
							value = rest
						}
					} else {
						if i+1 >= len(args) {
							return opts, "", false, perr("expected argument for flag `-c, --count'")
						}
						i++
						value = args[i]
					}
					if err := setCount(value); err != nil {
						return opts, "", false, err
					}
					j = len(arg)
				case 'P':
					opts.Privilege = true
					j++
				case 'V':
					opts.Version = true
					j++
				case 'h':
					opts.Help = true
					j++
				default:
					return opts, "", false, perr("unknown flag `%c'", c)
				}
			}
			i++
			continue
		}
		positional = append(positional, arg)
		i++
	}

	switch len(positional) {
	case 0:
	case 1:
		host = positional[0]
		hasHost = true
	default:
		return opts, "", false, fmt.Errorf("too many arguments")
	}
	return
}
