        if r > max { max = r }
        sum += r
    }
    avg := sum / time.Duration(len(rtts))
    var sq float64
    for _, r := range rtts {
        d := float64(r - avg)
        sq += d * d
    }
    std := time.Duration(math.Sqrt(sq / float64(len(rtts))))
    fmt.Printf("min=%s avg=%s max=%s stddev=%s\n", min, avg, max, std)
}
EOF
